	ch := make(chan CheckResult, 1)
	if os.Getenv("OKDCTL_NO_UPDATE_CHECK") == "1" {
		ch <- CheckResult{}
		return ch
	}
	go func() {
		ch <- runCheck(ctx)
	}()

